# Final verification of all tool modes
import subprocess
results = {}

# Test --quick
r = subprocess.run(['python3', '-m', 'fedmarket', '--quick'], capture_output=True, text=True)
results['quick'] = {'exit': r.returncode, 'output': r.stdout[:200]}

# Test --survival for 7030
r = subprocess.run(['python3', '-m', 'fedmarket', '--survival', '--code', '7030'], capture_output=True, text=True)
results['survival_7030'] = {'exit': r.returncode, 'output': r.stdout[:200]}

# Test --explore
r = subprocess.run(['python3', '-m', 'fedmarket', '--explore'], capture_output=True, text=True)
results['explore'] = {'exit': r.returncode, 'output': r.stdout[:200]}

# Test --quick --code DA10
r = subprocess.run(['python3', '-m', 'fedmarket', '--quick', '--code', 'DA10'], capture_output=True, text=True)
results['quick_da10'] = {'exit': r.returncode, 'output': r.stdout[:200]}

for name, data in results.items():
    print(f'{name}: exit={data["exit"]}')
    print(data['output'])
    print('---')
